/*
 * A208335  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A208834; see the Formula section.
 * https://oeis.org/A208335
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = coefficient of x^{n - r(r-1)/2 - 1} in v_r(x), * where r
 *            is the row number satisfying r(r-1)/2 < n ≤ r(r+1)/2. * The
 *            polynomials are generated by: * u_1(x)=1, v_1(x)=1 *
 *            u_{k+1}(x)=u_k(x)+x*v_k(x) * v_{k+1}(x)=(x+1)*u_k(x)+v_k(x) *
 *            Example triangle: * 1; * 2,1; * 3,3,1; * 4,7,5,1;
 * Range:     u8 n <= 38, u16 n <= 66, u32 n <= 66, u64 n <= 66, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

seq_t a(idx_t n) {
    if (n == 0) return 0;                 /* below offset, value irrelevant */

    /* Find the row r such that r(r-1)/2 < n ≤ r(r+1)/2 */
    size_t r = 1;
    while ((uint64_t)r * (r + 1ULL) / 2ULL < n) r++;

    /* Position within the row (0‑based) */
    size_t prev_sum = r * (r - 1ULL) / 2ULL;
    size_t pos = (size_t)n - prev_sum - 1ULL;

    /* Enough space for r up to about 200 (sufficient for n≈10 000) */
    enum { MAX_R = 200 };
    seq_t u[MAX_R];
    seq_t v[MAX_R];
    seq_t new_u[MAX_R];
    seq_t new_v[MAX_R];

    size_t cur_len = 1;
    u[0] = 1;   /* u_1(x)=1 */
    v[0] = 1;   /* v_1(x)=1 */

    /* Compute polynomials up to row r */
    for (size_t cur = 1; cur < r; ++cur) {
        size_t new_len = cur_len + 1;

        /* constant terms */
        new_u[0] = u[0];
        new_v[0] = v[0] + u[0];

        for (size_t k = 1; k < new_len; ++k) {
            seq_t u_k = (k < cur_len) ? u[k] : 0;
            seq_t v_k = (k < cur_len) ? v[k] : 0;
            new_u[k] = u_k + v[k - 1];
            new_v[k] = v_k + u_k + u[k - 1];
        }

        /* copy back to u and v for next iteration */
        for (size_t k = 0; k < new_len; ++k) {
            u[k] = new_u[k];
            v[k] = new_v[k];
        }
        cur_len = new_len;
    }

    /* Return the requested coefficient */
    return v[pos];
}
